# Generated by Claude Agentic SDLC Workflow
from flask import Blueprint, abort, flash, g, redirect, render_template, request, url_for

from .auth import login_required
from .db import get_db, utcnow_iso

bp = Blueprint("blog", __name__)

MAX_POST_TITLE_CHARS = 150
MAX_POST_CONTENT_CHARS = 10_000
MAX_SEARCH_CHARS = 100
SNIPPET_LENGTH = 150

# Whitelisted ORDER BY clauses; user input only selects a key, never reaches SQL.
SORTS = {
    "date_desc": "p.updated_at DESC, p.id DESC",
    "date_asc": "p.updated_at ASC, p.id ASC",
    "title_asc": "p.title COLLATE NOCASE ASC, p.id ASC",
    "title_desc": "p.title COLLATE NOCASE DESC, p.id DESC",
}
SORT_LABELS = [
    ("date_desc", "Date modified: newest first"),
    ("date_asc", "Date modified: oldest first"),
    ("title_asc", "Title: A-Z"),
    ("title_desc", "Title: Z-A"),
]
DEFAULT_SORT = "date_desc"

POST_COLUMNS = "p.id, p.author_id, p.title, p.content, p.created_at, p.updated_at, u.username AS author"


def make_snippet(text, length=SNIPPET_LENGTH):
    flat = " ".join(text.split())
    if len(flat) <= length:
        return flat
    return flat[:length].rstrip() + "..."


def _escape_like(term):
    return term.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def _read_post_form():
    title = request.form.get("title", "").strip()
    content = request.form.get("content", "").strip()
    errors = []
    if not title:
        errors.append("Title is required.")
    elif len(title) > MAX_POST_TITLE_CHARS:
        errors.append(f"Title must be at most {MAX_POST_TITLE_CHARS} characters.")
    if not content:
        errors.append("Content is required.")
    elif len(content) > MAX_POST_CONTENT_CHARS:
        errors.append(f"Content must be at most {MAX_POST_CONTENT_CHARS} characters.")
    return title, content, errors


def _render_form(heading, title, content, errors=(), status=200):
    return render_template("blog/form.html", heading=heading, title=title, content=content, errors=errors), status


def _get_post_or_404(post_id):
    post = get_db().execute(
        f"SELECT {POST_COLUMNS} FROM post p JOIN user u ON u.id = p.author_id WHERE p.id = ?",
        (post_id,),
    ).fetchone()
    if post is None:
        abort(404)
    return post


def _get_owned_post(post_id):
    post = _get_post_or_404(post_id)
    if post["author_id"] != g.user["id"]:
        abort(403)
    return post


@bp.route("/")
@login_required
def index():
    query = request.args.get("q", "").strip()[:MAX_SEARCH_CHARS]
    sort = request.args.get("sort", DEFAULT_SORT)
    if sort not in SORTS:
        sort = DEFAULT_SORT

    sql = f"SELECT {POST_COLUMNS} FROM post p JOIN user u ON u.id = p.author_id"
    params = []
    if query:
        sql += " WHERE (p.title LIKE ? ESCAPE '\\' OR p.content LIKE ? ESCAPE '\\')"
        pattern = f"%{_escape_like(query)}%"
        params = [pattern, pattern]
    sql += f" ORDER BY {SORTS[sort]}"

    rows = get_db().execute(sql, params).fetchall()
    posts = [{**dict(row), "snippet": make_snippet(row["content"])} for row in rows]
    return render_template("blog/index.html", posts=posts, q=query, sort=sort, sort_options=SORT_LABELS)


@bp.route("/blog/<int:post_id>")
@login_required
def detail(post_id):
    post = _get_post_or_404(post_id)
    return render_template("blog/detail.html", post=post)


@bp.route("/blog/create", methods=("GET", "POST"))
@login_required
def create():
    if request.method == "GET":
        return _render_form("Create Blog", "", "")

    title, content, errors = _read_post_form()
    if errors:
        return _render_form("Create Blog", title, content, errors, 400)

    db = get_db()
    timestamp = utcnow_iso()
    cursor = db.execute(
        "INSERT INTO post (author_id, title, content, created_at, updated_at) VALUES (?, ?, ?, ?, ?)",
        (g.user["id"], title, content, timestamp, timestamp),
    )
    db.commit()
    flash("Blog published.")
    return redirect(url_for("blog.detail", post_id=cursor.lastrowid))


@bp.route("/blog/<int:post_id>/edit", methods=("GET", "POST"))
@login_required
def edit(post_id):
    post = _get_owned_post(post_id)
    if request.method == "GET":
        return _render_form("Edit Blog", post["title"], post["content"])

    title, content, errors = _read_post_form()
    if errors:
        return _render_form("Edit Blog", title, content, errors, 400)

    db = get_db()
    db.execute(
        "UPDATE post SET title = ?, content = ?, updated_at = ? WHERE id = ?",
        (title, content, utcnow_iso(), post_id),
    )
    db.commit()
    flash("Blog updated.")
    return redirect(url_for("blog.detail", post_id=post_id))


@bp.route("/blog/<int:post_id>/delete", methods=("GET", "POST"))
@login_required
def delete(post_id):
    post = _get_owned_post(post_id)
    if request.method == "GET":
        return render_template("blog/delete.html", post=post)

    db = get_db()
    db.execute("DELETE FROM post WHERE id = ?", (post_id,))
    db.commit()
    flash("Blog deleted.")
    return redirect(url_for("blog.index"))
